//go:build darwin || linux || windows

package sandbox

import (
	"hash/fnv"
	"os"
	"path"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"time"

	"github.com/samyfodil/laboon/core"
	"github.com/samyfodil/laboon/filesystems/hostfs"
)

// Synthetic /proc, /sys and /dev. The rootfs carries none of them, so the
// overlay hands paths below these mounts to pseudo(), which builds the node on
// demand from the supervisor's process registry and the host's state. A file's
// content lives in memory (memFile): generated by the first read and again by
// any later read from offset 0, as Linux's seq_files do, so a reader that
// rewinds (top) sees fresh figures. Devices and directories are host-backed.

type pkind uint8

const (
	pDir   pkind = iota
	pFile        // content from gen at open
	pLink        // symlink to target
	pDev         // character device backed by a host device
	pFdObj       // /proc/<pid>/fd/<n> naming a non-path object (pipe, socket...)
)

// Linux st_dev of the pseudo mounts (anonymous block devices 0:N).
const (
	devProc   = 0x16
	devSys    = 0x15
	devDevtmp = 0x05
)

type procMemIO func(addr uint64, b []byte, write bool) error

var openProcMem func(r, target *dguest) (procMemIO, lxErrno)

type pnode struct {
	mem    *dguest
	kind   pkind
	perm   uint32
	dev    uint64
	ino    uint64
	gen    func(r *dguest) []byte            // r is the reading guest
	kids   func() []pchild                   // pDir: the listed children
	nlink  func() uint32                     // pDir: its link count, if cheaper than counting kids
	find   func(string) *pnode               // pDir: lookup of unlisted names (/proc/<tid>)
	look   func(string) *pnode               // pDir: lookup without building the listing (fd/)
	target string                            // pLink, and the readlink text of a pFdObj
	host   string                            // pDev host device
	rdev   uint64                            // pDev Linux device number
	fd     *dfile                            // pFdObj
	write  bool                              // pFile: writes accepted (and dropped unless put)
	put    func(w *dguest, b []byte) lxErrno // pFile: applies a write
}

type pchild struct {
	name string
	n    *pnode
}

func pdir(kids func() []pchild) *pnode { return &pnode{kind: pDir, perm: 0o555, kids: kids} }
func pfile(gen func() []byte) *pnode {
	return &pnode{kind: pFile, perm: 0o444, gen: func(*dguest) []byte { return gen() }}
}
func pfileR(gen func(r *dguest) []byte) *pnode { return &pnode{kind: pFile, perm: 0o444, gen: gen} }
func pstr(s string) *pnode                     { return pfile(func() []byte { return []byte(s) }) }
func pwfile(s string) *pnode {
	return &pnode{kind: pFile, perm: 0o644, gen: func(*dguest) []byte { return []byte(s) }, write: true}
}

// pmap is a writable /proc file (uid_map, gid_map, setgroups) whose write put
// applies.
func pmap(s string, put func(w *dguest, b []byte) lxErrno) *pnode {
	return &pnode{kind: pFile, perm: 0o644, gen: func(*dguest) []byte { return []byte(s) }, write: true, put: put}
}
func plink(t string) *pnode { return &pnode{kind: pLink, perm: 0o777, target: t} }

// exeNode serves /proc/<pid>/exe. When the exec'd file is pinned it is a
// descriptor-backed magic link (openable after its path is gone, with the
// " (deleted)" suffix Linux shows); otherwise it is a plain symlink to the
// exe path.
func (g *dguest) exeNode(exe string, pin *dfile) *pnode {
	if pin == nil {
		return plink(exe)
	}
	target := exe
	if _, e := g.lstatGuest(exe); e == lxENOENT {
		target += " (deleted)"
	}
	return &pnode{kind: pFdObj, perm: 0o777, fd: pin, target: target}
}

func (n *pnode) child(name string) *pnode {
	if n.look != nil {
		return n.look(name)
	}
	if n.kids != nil {
		for _, c := range n.kids() {
			if c.name == name {
				return c.n
			}
		}
	}
	if n.find != nil {
		return n.find(name)
	}
	return nil
}

// pfi is a pseudo node's os.FileInfo; Sys returns the node.
type pfi struct {
	name string
	n    *pnode
}

func (f pfi) Name() string { return f.name }
func (f pfi) Size() int64 {
	if f.n.kind == pLink || f.n.kind == pFdObj {
		return int64(len(f.n.target))
	}
	return 0
}
func (f pfi) Mode() os.FileMode {
	m := os.FileMode(f.n.perm & 0o777)
	switch f.n.kind {
	case pDir:
		m |= os.ModeDir
	case pLink, pFdObj:
		m |= os.ModeSymlink
	case pDev:
		m |= os.ModeDevice | os.ModeCharDevice
	}
	if f.n.perm&0o1000 != 0 {
		m |= os.ModeSticky
	}
	return m
}
func (f pfi) ModTime() time.Time { return time.Now() }
func (f pfi) IsDir() bool        { return f.n.kind == pDir }
func (f pfi) Sys() any           { return f.n }

// ---- process registry view ---------------------------------------------------

// procState is the run-wide part of the pseudo filesystems.
type procState struct {
	stubPid int         // host pid of the main stub (guest pid 1)
	boot    *procInfo   // pid 1's program
	stdio   [3]*os.File // the files behind the main stub's fds 0-2
	bootID  string
}

// procInfo is what /proc shows of one guest process (thread group): the
// program, its argv and env, its start time and the mappings the
// supervisor made for it. Threads share their process's.
type procInfo struct {
	mu     sync.Mutex
	exe    string
	exePin *dfile // the exec'd file, pinned so /proc/<pid>/exe resolves it after its name is removed (nil: fall back to the exe path)
	comm   string // the name exec was given; "" means exe's
	argv   []string
	env    []string
	start  time.Time
	vmas   []vma
	img    *imgInfo // the stub's record of the loaded images, fetched lazily
	interp string   // guest path of the program's PT_INTERP, "" if static
}

type vma struct {
	lo, hi uint64
	prot   uint64
	shared bool
	off    uint64
	ino    uint64
	path   string
}

// imgInfo mirrors stub/macos/procinfo.zig's Info.
type imgInfo struct {
	sp, mainLo, mainHi, interpLo, interpHi, stackLo, stackHi uint64
}

func (fs *dfs) initProcfs(stubPid int, exe string, argv, env []string, stdio [3]*os.File) {
	fs.pst.stubPid = stubPid
	fs.pst.stdio = stdio
	fs.pst.bootID = randomUUID()
	if env == nil {
		env = []string{} // a nil env is empty, never the supervisor's own
	}
	fs.pst.boot = &procInfo{exe: exe, argv: argv, env: env, start: time.Now()}
	if fs.upperAbs != "" {
		fs.provisionShm()
	}
}

// provisionShm makes /dev/shm a sticky world-writable directory, as the
// kernel's shm tmpfs is, creating it and /dev in the writable layer if absent.
func (fs *dfs) provisionShm() {
	cur, err := fs.ns.Resolve("/", true)
	if err != nil {
		return
	}
	for _, name := range []string{"dev", "shm"} {
		child, err := cur.FS.Lookup(cur.Node, name)
		if err != nil {
			child, err = cur.FS.Create(cur.Node, name, core.CreateSpec{Kind: core.Dir, Mode: 0o755})
		}
		if err != nil || child.Kind() != core.Dir {
			return
		}
		cur.Node = child
	}
	mode := uint32(0o1777)
	cur.Node.SetAttr(core.AttrUpdate{Mode: &mode})
}

func (pi *procInfo) forked() *procInfo {
	pi.mu.Lock()
	defer pi.mu.Unlock()
	if pi.exePin != nil {
		pi.exePin.refs.Add(1)
	}
	return &procInfo{exe: pi.exe, exePin: pi.exePin, comm: pi.comm, argv: pi.argv, env: pi.env, start: time.Now(),
		vmas: append([]vma(nil), pi.vmas...), img: pi.img, interp: pi.interp}
}

// noteExec records the new program. The env is not replaced: the stub enters
// the new image with its own (inherited) environment, which is what the guest
// actually sees.
func (g *dguest) noteExec(gp, prog string, argv []string, pin *dfile) {
	pi := g.pi
	pi.mu.Lock()
	if pi.exePin != nil {
		pi.exePin.unref()
	}
	pi.exe, pi.exePin, pi.comm, pi.argv, pi.vmas, pi.img, pi.interp = gp, pin, path.Base(prog), argv, nil, nil, ""
	pi.mu.Unlock()
}

// dropExe lets go of the exec'd file at the process's end.
func (pi *procInfo) dropExe() {
	pi.mu.Lock()
	if pi.exePin != nil {
		pi.exePin.unref()
		pi.exePin = nil
	}
	pi.mu.Unlock()
}

// noteMmap records a mapping the supervisor made (ret is mmap's result).
func (g *dguest) noteMmap(ret int64, length, prot, flags uint64, d *dfile) {
	if ret < 0 || length == 0 {
		return
	}
	lo := uint64(ret)
	v := vma{lo: lo, hi: lo + (length+darwinPage-1)&^(darwinPage-1), prot: prot, shared: flags&0x3 == 1}
	if d != nil {
		v.path = d.gp
		if d.held() {
			_, v.ino = d.hostDevIno()
		}
	}
	pi := g.pi
	pi.mu.Lock()
	pi.vmas = cutVmas(pi.vmas, v.lo, v.hi)
	pi.vmas = append(pi.vmas, v)
	fetch := pi.img == nil
	pi.mu.Unlock()
	if fetch {
		g.imgInfoOf(g) // so other processes can show this one's images too
	}
}

func (g *dguest) noteMunmap(addr, length uint64) {
	pi := g.pi
	pi.mu.Lock()
	pi.vmas = cutVmas(pi.vmas, addr, addr+(length+darwinPage-1)&^(darwinPage-1))
	pi.mu.Unlock()
}

// cutVmas removes [lo, hi) from vs, splitting mappings it cuts through.
func cutVmas(vs []vma, lo, hi uint64) []vma {
	out := vs[:0:0]
	for _, v := range vs {
		if v.hi <= lo || v.lo >= hi {
			out = append(out, v)
			continue
		}
		if v.lo < lo {
			l := v
			l.hi = lo
			out = append(out, l)
		}
		if v.hi > hi {
			r := v
			if r.path != "" {
				r.off += hi - v.lo
			}
			r.lo = hi
			out = append(out, r)
		}
	}
	return out
}

// guests returns every live guest (processes and threads).
func (fs *dfs) guests() []*dguest {
	fs.mu.Lock()
	defer fs.mu.Unlock()
	out := make([]*dguest, 0, len(fs.procs))
	for _, p := range fs.procs {
		if p.g != nil {
			out = append(out, p.g)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].pid < out[j].pid })
	return out
}

func (fs *dfs) guest(pid int) *dguest {
	fs.mu.Lock()
	defer fs.mu.Unlock()
	if p := fs.procs[pid]; p != nil {
		return p.g
	}
	return nil
}

// threadsOf returns the live threads of thread group tgid, leader first.
func (fs *dfs) threadsOf(tgid int) []*dguest {
	var out []*dguest
	for _, t := range fs.guests() {
		if t.tgid == tgid {
			out = append(out, t)
		}
	}
	return out
}

// hostPidOf is the host pid of the stub running guest process tgid.
func (fs *dfs) hostPidOf(tgid int) int {
	fs.mu.Lock()
	ospid := 0
	if p := fs.pt[tgid]; p != nil {
		ospid = p.ospid // follows an exec into a fresh stub
	} else if p := fs.procs[tgid]; p != nil {
		ospid = p.ospid
	}
	fs.mu.Unlock()
	if ospid > 0 {
		return ospid
	}
	if tgid == 1 {
		return fs.pst.stubPid
	}
	return 0
}

// ---- path dispatch -----------------------------------------------------------

// pseudoMount reports whether gp lies in a synthetic filesystem (a proc, sysfs
// or cgroup2 instance, or /dev), by the mount that covers it.
func (g *dguest) pseudoMount(gp string) bool {
	_, mfs := g.vns().MountOf(gp)
	switch mfs.(type) {
	case *pnodeFS, *devFS:
		return true
	}
	return false
}

// pseudoNode is the synthetic node behind a resolved node, if it is one. pure
// reports a node with no overlay entry behind it (a missing name under it is
// missing, not left for the overlay).
func pseudoNode(n core.Node) (pn *pnode, pure bool) {
	switch n := n.(type) {
	case *pnodeNode:
		return n.n, true
	case *devNodeU:
		return n.syn, n.ov == nil
	}
	return nil, false
}

// pseudo returns the synthetic node at a resolved guest path. handled is false
// when the path is not synthetic (the overlay serves it: the rest of /dev,
// /dev/shm). A missing name is the synthetic filesystem's answer when the
// nearest directory above it that exists is purely synthetic.
func (g *dguest) pseudo(gp string) (n *pnode, e lxErrno, handled bool) {
	if !g.pseudoMount(gp) {
		return nil, 0, false
	}
	ns := g.vns()
	loc, err := ns.Resolve(gp, false)
	if err == nil {
		n, _ := pseudoNode(loc.Node)
		return n, 0, n != nil
	}
	for p := path.Dir(gp); ; p = path.Dir(p) {
		if l, perr := ns.Resolve(p, false); perr == nil {
			if n, pure := pseudoNode(l.Node); n != nil && pure {
				return nil, osErrno(err), true
			}
			return nil, 0, false
		}
		if p == "/" {
			return nil, 0, false
		}
	}
}

func pino(gp string) uint64 {
	if gp == "/proc" || gp == "/sys" || gp == "/dev" {
		return 1 // a mount's root
	}
	h := fnv.New64a()
	h.Write([]byte(gp))
	return h.Sum64()>>1 | 1
}

// pseudoLink is linkTarget's view of a synthetic path. A magic link whose
// target names an object rather than a path (e.g. /proc/<pid>/ns/user ->
// "user:[4026531837]") is not followed: like the kernel's nsfs links it
// resolves to itself, so stat and access on the link succeed while readlink
// still shows the token.
func (g *dguest) pseudoLink(gp string) (target string, ok, handled bool) {
	n, e, handled := g.pseudo(gp)
	if !handled || e != 0 || n.kind != pLink || magicTarget(n.target) {
		return "", false, handled
	}
	return n.target, true, true
}

// magicTarget reports whether a symlink target names an object (no slash, a
// "name:[id]" token) rather than a path to resolve.
func magicTarget(t string) bool {
	return !strings.Contains(t, "/") && strings.Contains(t, ":[")
}

func (g *dguest) pseudoReadlink(gp string) (string, lxErrno, bool) {
	n, e, handled := g.pseudo(gp)
	if !handled || e != 0 {
		return "", e, handled
	}
	if n.kind == pLink || n.kind == pFdObj {
		return n.target, 0, true
	}
	return "", lxEINVAL, true
}

func (g *dguest) pseudoStat(gp string) (os.FileInfo, lxErrno, bool) {
	n, e, handled := g.pseudo(gp)
	if !handled || e != 0 {
		return nil, e, handled
	}
	return pfi{name: path.Base(gp), n: n}, 0, true
}

// fileInfo is fstat's view of an open file: a pseudo file reports its node
// (procfs files are size 0, devices are character devices), anything else the
// host file.
func (g *dguest) fileInfo(d *dfile) (os.FileInfo, error) {
	if !d.tty && g.pseudoMount(d.gp) {
		if fi, e, ok := g.pseudoStat(d.gp); ok && e == 0 {
			return fi, nil
		}
	}
	return hostfs.FileStat(d.f)
}

// pseudoChange answers mkdir (create) or unlink of a synthetic path, which
// procfs and sysfs refuse; handled is false for overlay paths.
func (g *dguest) pseudoChange(gp string, create bool) (int64, bool) {
	if at, mfs := g.vns().MountOf(gp); gp != at && isCgroupFS(mfs) {
		return sErr(g.cgStore().change(cgRoot+gp[len(at):], create)), true // a cgroup mkdir/rmdir
	}
	_, e, handled := g.pseudo(gp)
	switch {
	case !handled:
		return 0, false
	case e == 0 && create:
		return sErr(lxEEXIST), true
	case e == lxENOENT && (!create || strings.HasPrefix(gp, "/proc")):
		return sErr(lxENOENT), true // procfs lookups fail rather than go negative
	case e != 0 && e != lxENOENT:
		return sErr(e), true
	}
	return sErr(lxEPERM), true
}

// pipeIO is an optional supervisor transport. Unix keeps using host pipes.
// Counts are open descriptions, not fd entries (dup/fork share a dfile).
type pipeIO interface {
	read(g *dguest, d *dfile, b []byte, nb, whole bool) (int, error) // whole: only if all it holds fits in b
	write(*dguest, *dfile, []byte, bool) (int, error)
	open(int64)
	close(int64)
	resize(int32) lxErrno
}

// pipeObj links a pipe's two ends so either can be reopened through the other
// (open of /proc/<pid>/fd/<n> with the other access mode).
type pipeObj struct {
	io   pipeIO
	mu   sync.Mutex
	ends [2]*dfile     // a live description of the read and the write end
	sz   atomic.Int32  // F_SETPIPE_SZ capacity, 0 for the default
	perm atomic.Uint32 // permSet | the mode fchmod gave the pipe's inode, which both ends share
}

// perm is where the mode fchmod gave d's object lives when the host keeps
// none for it: a pipe's on the pipe, which both ends share as their inode,
// anything else's on the description.
func (d *dfile) perm() *atomic.Uint32 {
	if d.pipe != nil {
		return &d.pipe.perm
	}
	return &d.fx.perm
}

// pipeSize is the capacity F_GETPIPE_SZ reports, shared by both ends of a
// pipe the supervisor made.
func (d *dfile) pipeSize() *atomic.Int32 {
	if d.pipe != nil {
		return &d.pipe.sz
	}
	return &d.fx.pipeSz
}

func (p *pipeObj) end(w int) *dfile {
	p.mu.Lock()
	defer p.mu.Unlock()
	if d := p.ends[w]; d != nil && d.refs.Load() > 0 {
		return d
	}
	return nil
}

func (p *pipeObj) keep(w int, d *dfile) {
	p.mu.Lock()
	if p.ends[w] == nil || p.ends[w].refs.Load() <= 0 {
		p.ends[w] = d
	}
	p.mu.Unlock()
}

// reopen is open(2) of a magic link naming an object without a usable path.
// Linux opens a new description of the object. Here a pipe gets the matching
// end's host fd duplicated, an unlinked file its held fd duplicated (sharing
// the offset: Darwin cannot reopen it), and stub stdio keeps its own
// description when the mode is the one it has.
func (g *dguest) reopen(d *dfile, flags int64) (*dfile, lxErrno) {
	acc := flags & lxOAccmod
	if d.stub >= 0 {
		own := int64(lxOWronly)
		if d.stub == 0 {
			own = lxORdonly
		}
		if acc == own && flags&lxONonblock == 0 {
			return d, 0
		}
		if d.feed != nil {
			d.feed.stream() // the new description reads the pipe without asking
		}
		var h *os.File
		if d.stub < 3 {
			h = g.pst.stdio[d.stub]
		}
		if h == nil { // exec gave the stub /dev/null
			f, err := os.OpenFile("/dev/null", goOpenFlags(flags)&^(os.O_CREATE|os.O_TRUNC|os.O_EXCL), 0)
			if err != nil {
				return nil, osErrno(err)
			}
			return &dfile{f: f, gp: "/dev/null", stub: -1}, 0
		}
		if f, e := dupMode(h, acc); e == 0 {
			return &dfile{f: f, stub: -1}, 0
		}
		if st, err := hostfs.FstatOf(h); err == nil && st.Mode()&lxSIFMT == lxSIFCHR {
			if f, err := os.OpenFile("/dev/tty", goOpenFlags(flags)&^(os.O_CREATE|os.O_TRUNC|os.O_EXCL), 0); err == nil {
				return &dfile{f: f, stub: -1}, 0
			}
		}
		return nil, lxENXIO
	}
	if d.pinned != nil {
		return g.reopen(d.pinned, flags)
	}
	if d.pathFD != nil {
		// A pinned O_PATH handle (an O_PATH fd or /proc/<pid>/exe): re-open the
		// object it holds, with the requested access mode, surviving its name
		// being removed (a runtime reopens its unlinked exec fifo O_WRONLY here).
		hf := goOpenFlags(flags)
		if flags&lxONonblock != 0 {
			hf |= hostfs.HostONonblock
		}
		rf, e := reopenMode(d.pathFD, hf)
		if e != 0 {
			return nil, e
		}
		return &dfile{f: rf, gp: d.gp, stub: -1}, 0
	}
	if d.vf != nil {
		// A regular file: a new description of the same open file, with an offset
		// of its own, through a second handle on it.
		if own := d.fx.oflags & lxOAccmod; d.fx.hasFlags && own != lxORdwr && own != acc {
			return nil, lxEACCES
		}
		du, ok := d.vf.(interface{ Dup() (core.File, error) })
		if !ok {
			return d, 0 // a backing with no second handle: the description itself
		}
		nf, err := du.Dup()
		if err != nil {
			return nil, osErrno(err)
		}
		nd := &dfile{gp: d.gp, stub: -1, vf: nf, vn: d.vn, fs: d.fs}
		if d.hf != nil {
			nd.hf = nf
		}
		return nd, 0
	}
	if d.f == nil || d.ev != nil || d.ep != nil {
		return d, 0
	}
	if p := d.pipe; p != nil {
		if p.io != nil {
			f, e := pipeIOFile(p.io, d, acc)
			if e != 0 {
				return nil, e
			}
			p.io.open(acc)
			nd := &dfile{f: f, gp: d.gp, stub: -1, pipe: p}
			nd.fx.oflags, nd.fx.hasFlags = acc, true
			return nd, 0
		}
		w, src := 0, d
		switch acc {
		case lxORdonly:
			src = p.end(0)
		case lxOWronly:
			w, src = 1, p.end(1)
		}
		if src == nil {
			return nil, lxENXIO
		}
		f, e := dupFile(src.f)
		if e != 0 {
			return nil, lxENXIO
		}
		nd := &dfile{f: f, gp: "pipe:", stub: -1, pipe: p}
		if acc != lxORdwr {
			p.keep(w, nd)
		}
		return nd, 0
	}
	st, err := hostfs.FstatOf(d.f)
	if err != nil {
		return nil, lxEBADF
	}
	if st.Mode()&lxSIFMT == lxSIFSCK {
		return nil, lxENXIO
	}
	f, e := dupMode(d.f, acc)
	if e != 0 {
		return nil, e
	}
	return &dfile{f: f, gp: d.gp, isDir: d.isDir, stub: -1}, 0
}

// dupMode is dupFile when f's host access mode allows acc, EACCES otherwise.
func dupMode(f *os.File, acc int64) (*os.File, lxErrno) {
	host, _, err := hostAccMode(f)
	if err != nil {
		return nil, lxEBADF
	}
	if host != lxORdwr && host != acc {
		return nil, lxEACCES
	}
	return dupFile(f)
}

// pseudoOpen opens a synthetic path; handled is false for overlay paths.
func (g *dguest) pseudoOpen(gp string, flags int64) (int64, bool) {
	n, e, handled := g.pseudo(gp)
	if !handled {
		return 0, false
	}
	if e != 0 {
		return sErr(e), true
	}
	wr := flags&lxOAccmod != lxORdonly
	if flags&lxOCreat != 0 && flags&lxOExcl != 0 {
		return sErr(lxEEXIST), true
	}
	if flags&lxODirectory != 0 && n.kind != pDir {
		return sErr(lxENOTDIR), true
	}
	var d *dfile
	switch n.kind {
	case pDir:
		if wr {
			return sErr(lxEISDIR), true
		}
		f, err := g.dfs.openEmpty()
		if err != nil {
			return sErr(osErrno(err)), true
		}
		d = &dfile{f: f, gp: gp, isDir: true, stub: -1}
	case pFile:
		if wr && !n.write {
			return sErr(lxEACCES), true
		}
		m := &memFile{n: n, name: path.Base(gp), rd: flags&lxOAccmod != lxOWronly, wr: wr}
		if n.mem != nil {
			m.memory, e = openProcMem(g, n.mem)
			if e != 0 {
				return sErr(e), true
			}
		}
		d = &dfile{gp: gp, stub: -1, mem: m}
	case pDev:
		f, err := hostDevOpen(n.host, goOpenFlags(flags)&^(os.O_CREATE|os.O_TRUNC|os.O_EXCL))
		if err != nil {
			return sErr(osErrno(err)), true
		}
		d = &dfile{f: f, gp: gp, stub: -1, full: n.rdev == lxMakedev(1, 7)}
	case pFdObj:
		if d, e = g.reopen(n.fd, flags); e != 0 {
			return sErr(e), true
		}
	case pLink:
		// A magic namespace link (net:[inode], user:[inode], ...) opens like the
		// kernel's nsfs: a handle to the namespace, not a path to follow. A plain
		// symlink is never opened here (path resolution follows it first). Back
		// the handle with an empty read-only file carrying the link's namespace
		// inode so fstat identifies it and setns through the fd joins it
		// (lx_setns.go); a container runtime (docker's libnetwork) opens
		// /proc/self/ns/net to make a netlink handle for its network namespace.
		if !magicTarget(n.target) {
			return sErr(lxELOOP), true
		}
		d = &dfile{gp: gp, stub: -1, mem: &memFile{n: n, name: path.Base(gp), rd: true}}
	default:
		return sErr(lxELOOP), true
	}
	if d != n.fd {
		d.nonblock.Store(flags&lxONonblock != 0)
		d.fx.oflags, d.fx.hasFlags = flags&lxOStatusKeep|lxOLargefile, true
	}
	fd := g.ft.add(d, 0)
	if flags&lxOCloexec != 0 {
		g.ft.setCloexec(fd, true)
	}
	return int64(fd), true
}

// openEmpty opens the run's own empty, read-only directory: the descriptor
// behind a directory with no host directory of its own (a synthetic /proc or
// /sys one, an in-memory one), which fstat and fchdir need. Its listing and
// every path under it are answered through the Namespace by name.
func (fs *dfs) openEmpty() (*os.File, error) {
	fs.emptyOnce.Do(func() {
		fs.emptyPath, fs.emptyErr = os.MkdirTemp(fs.tmpDir, "lc-empty-")
		if fs.emptyErr == nil {
			fs.emptyErr = os.Chmod(fs.emptyPath, 0o555)
		}
	})
	if fs.emptyErr != nil {
		return nil, fs.emptyErr
	}
	return os.Open(fs.emptyPath)
}

// memFile is an open non-host file: it has no host file (dfile.f is nil), so
// generic fd code treats it as a non-host fd and read, write, lseek and fstat ask
// memOf. It serves two kinds. A synthetic file (/proc, /sys) generates its bytes
// on demand from a pnode (n). An in-memory backend file (tmpfs, WithMount) reads and
// writes real content through a core.File handle (vf) over a core.Node (vn).
type memFile struct {
	memory procMemIO
	mu     sync.Mutex
	n      *pnode
	name   string
	rd     bool
	wr     bool
	data   []byte
	pos    int64
	done   bool // data generated

	vn core.Node // a non-host directory placeholder's node, for fstat; nil for a synthetic file
}

func (m *memFile) accmode() uint64 {
	switch {
	case m.rd && m.wr:
		return lxORdwr
	case m.wr:
		return lxOWronly
	}
	return lxORdonly
}

func (g *dguest) memOf(fd int64) *memFile {
	if d, ok := g.ft.get(int(fd)); ok {
		return d.mem
	}
	return nil
}

// readAt returns up to n bytes at off, (re)generating the content first when
// reading from the start; mu held.
func (m *memFile) readAt(r *dguest, n, off int64) []byte {
	if !m.done || off == 0 {
		m.data = m.n.gen(r)
		m.done = true
	}
	if off >= int64(len(m.data)) {
		return nil
	}
	return m.data[off:min(off+n, int64(len(m.data)))]
}

// memRead serves read(2) on a synthetic file; ok is false for any other fd.
func (g *dguest) memRead(fd int64, bufAddr uint64, n int64) (int64, bool) {
	m := g.memOf(fd)
	if m == nil {
		return 0, false
	}
	if !m.rd {
		return sErr(lxEBADF), true
	}
	if n < 0 {
		return sErr(lxEINVAL), true
	}
	m.mu.Lock()
	if m.memory != nil {
		r := g.procMemIO(m, bufAddr, n, m.pos, false)
		if r > 0 {
			m.pos += r
		}
		m.mu.Unlock()
		return r, true
	}
	b := m.readAt(g, n, m.pos)
	m.pos += int64(len(b))
	m.mu.Unlock()
	if err := g.writeMem(bufAddr, b); err != nil {
		return sErr(lxEFAULT), true
	}
	return int64(len(b)), true
}

// memPread is pread64 on a synthetic file: the caller's offset, the
// description's left alone.
func (g *dguest) memPread(fd int64, bufAddr uint64, n, off int64) (int64, bool) {
	m := g.memOf(fd)
	if m == nil {
		return 0, false
	}
	if !m.rd {
		return sErr(lxEBADF), true
	}
	if n < 0 || off < 0 {
		return sErr(lxEINVAL), true
	}
	if m.memory != nil {
		return g.procMemIO(m, bufAddr, n, off, false), true
	}
	m.mu.Lock()
	b := m.readAt(g, n, off)
	m.mu.Unlock()
	if err := g.writeMem(bufAddr, b); err != nil {
		return sErr(lxEFAULT), true
	}
	return int64(len(b)), true
}

// memWrite accepts writes to a writable synthetic file (a tunable such as
// oom_score_adj) and drops them.
func (g *dguest) memWrite(fd int64, bufAddr uint64, n int64) (int64, bool) {
	m := g.memOf(fd)
	if m == nil {
		return 0, false
	}
	if !m.wr {
		return sErr(lxEBADF), true
	}
	if m.memory != nil {
		m.mu.Lock()
		defer m.mu.Unlock()
		r := g.procMemIO(m, bufAddr, n, m.pos, true)
		if r > 0 {
			m.pos += r
		}
		return r, true
	}
	if m.n.put != nil {
		b, err := g.readMem(bufAddr, int(min(n, 4096)))
		if err != nil {
			return sErr(lxEFAULT), true
		}
		if e := m.n.put(g, b); e != 0 {
			return sErr(e), true
		}
	}
	return n, true
}

func (g *dguest) memPwrite(fd int64, addr uint64, n, off int64) (int64, bool) {
	m := g.memOf(fd)
	if m == nil {
		return 0, false
	}
	if m.memory == nil {
		return 0, false
	}
	return g.procMemIO(m, addr, n, off, true), true
}

func (g *dguest) procMemIO(m *memFile, addr uint64, n, off int64, write bool) int64 {
	if write && !m.wr || !write && !m.rd {
		return sErr(lxEBADF)
	}
	if n < 0 || off < 0 || uint64(n) > ^uint64(0)-uint64(off) {
		return sErr(lxEINVAL)
	}
	var total int64
	for total < n {
		b := make([]byte, min(n-total, 4096-(off+total)%4096))
		if write {
			if g.getBuf(addr+uint64(total), b) != nil {
				if total != 0 {
					return total
				}
				return sErr(lxEFAULT)
			}
		}
		if m.memory(uint64(off+total), b, write) != nil {
			if total != 0 {
				return total
			}
			return sErr(lxEIO)
		}
		if !write && g.putBuf(addr+uint64(total), b) != nil {
			if total != 0 {
				return total
			}
			return sErr(lxEFAULT)
		}
		total += int64(len(b))
	}
	return total
}

func (g *dguest) memLseek(fd, off, whence int64) (int64, bool) {
	m := g.memOf(fd)
	if m == nil {
		return 0, false
	}
	m.mu.Lock()
	defer m.mu.Unlock()
	var base int64
	switch whence {
	case 0: // SEEK_SET
	case 1: // SEEK_CUR
		base = m.pos
	default: // a synthetic seq_file has no SEEK_END
		return sErr(lxEINVAL), true
	}
	if base+off < 0 {
		return sErr(lxEINVAL), true
	}
	m.pos = base + off
	return m.pos, true
}

// memStat is fstat's view of a synthetic file.
func (g *dguest) memStat(fd int64) (os.FileInfo, bool) {
	m := g.memOf(fd)
	if m == nil {
		return nil, false
	}
	return pfi{name: m.name, n: m.n}, true
}

// ---- /dev --------------------------------------------------------------------

// devNode returns the synthetic node /dev/<name>, nil if the overlay serves it.
// macOS has no /dev/full; /dev/zero stands in for reads and the description
// fails writes with ENOSPC (dfile.full).
func devNode(name string) *pnode {
	dev := func(host string, major, minor uint64) *pnode {
		return &pnode{kind: pDev, perm: 0o666, host: host, rdev: lxMakedev(major, minor)}
	}
	switch name {
	case "null":
		return dev("/dev/null", 1, 3)
	case "zero":
		return dev("/dev/zero", 1, 5)
	case "full":
		return dev("/dev/zero", 1, 7)
	case "random":
		return dev("/dev/random", 1, 8)
	case "urandom":
		return dev("/dev/urandom", 1, 9)
	case "tty":
		return dev("/dev/tty", 5, 0)
	case "ptmx":
		return dev("/dev/ptmx", 5, 2)
	case "stdin":
		return plink("/proc/self/fd/0")
	case "stdout":
		return plink("/proc/self/fd/1")
	case "stderr":
		return plink("/proc/self/fd/2")
	case "fd":
		return plink("/proc/self/fd")
	case "pts":
		return &pnode{kind: pDir, perm: 0o755, kids: func() []pchild { return nil }}
	}
	return nil
}

var devNames = []string{"null", "zero", "full", "random", "urandom", "tty", "ptmx", "stdin", "stdout", "stderr", "fd", "pts"}

func (g *dguest) devRoot() *pnode {
	n := pdir(func() []pchild {
		out := make([]pchild, 0, len(devNames))
		for _, name := range devNames {
			n := devNode(name)
			if name == "pts" {
				n = g.ptsDir()
			}
			out = append(out, pchild{name, n})
		}
		return out
	})
	n.perm = 0o755
	return n
}

// lxMakedev encodes a Linux dev_t.
func lxMakedev(major, minor uint64) uint64 {
	return minor&0xff | (major&0xfff)<<8 | (minor&^0xff)<<12 | (major&^0xfff)<<32
}

// lxModeOf is the Linux st_mode of fi.
func lxModeOf(fi os.FileInfo) uint32 {
	m := fi.Mode()
	mode := uint32(m.Perm())
	switch {
	case m.IsDir():
		mode |= 0x4000
	case m&os.ModeSymlink != 0:
		mode |= 0xa000
	case m&os.ModeCharDevice != 0:
		mode |= 0x2000
	case m&os.ModeDevice != 0:
		mode |= 0x6000
	case m&os.ModeNamedPipe != 0:
		mode |= 0x1000
	case m&os.ModeSocket != 0:
		mode |= 0xc000
	default:
		mode |= 0x8000
	}
	if m&os.ModeSetuid != 0 {
		mode |= 0o4000
	}
	if m&os.ModeSetgid != 0 {
		mode |= 0o2000
	}
	if m&os.ModeSticky != 0 {
		mode |= 0o1000
	}
	return mode
}

// lxRdev is the Linux st_rdev of fi: a pseudo device's own number, a host
// device's Darwin major/minor re-encoded.
func lxRdev(fi os.FileInfo) uint64 {
	switch s := fi.Sys().(type) {
	case *pnode:
		return s.rdev
	}
	if st, ok := hostfs.StatOf(fi); ok && fi.Mode()&os.ModeDevice != 0 {
		if r, ok := ttyRdev(fi); ok {
			return r
		}
		return st.Rdev()
	}
	return 0
}

func darwinRdev(r uint64) uint64 {
	if r == 0 {
		return 0
	}
	return lxMakedev(r>>24&0xff, r&0xffffff)
}

// ---- /proc/<pid>/fd ----------------------------------------------------------

// fdNode is the magic link /proc/<pid>/fd/<n> of t: an ordinary symlink to a
// file's guest path, or a pFdObj for an object without one (a pipe, socket,
// stdio, or a file since unlinked), which open reopens.
func (t *dguest) fdNode(d *dfile) *pnode {
	name := d.name()
	if d.fx.unnamed && strings.HasPrefix(name, "/") {
		return &pnode{kind: pFdObj, perm: 0o777, fd: d, target: name}
	}
	if (d.held() || d.mem != nil || d.fx.opath) && strings.HasPrefix(name, "/") {
		if t.pseudoMount(name) {
			return plink(name)
		}
		if d.fx.opath && (d.pathFD != nil || d.pinned != nil) {
			// An O_PATH fd pins its inode; /proc/<pid>/fd/<n> is the kernel's magic
			// link to that open object, not a re-resolution of the name it shows.
			// Open reopens the pinned descriptor, so it still works when the name is
			// gone or unreachable -- runc opens its exec fifo O_PATH before
			// pivot_root, then reopens it through /proc/self/fd (O_WRONLY) to start
			// the container, once the fifo sits outside the new root. A followed
			// stat reports the object's own identity (fdLinkStat), so fstat(fd) and
			// stat(/proc/self/fd/<n>) agree the way a runtime's fifo check expects.
			del := ""
			if _, e := t.lstatGuest(name); e == lxENOENT {
				del = " (deleted)"
			}
			return &pnode{kind: pFdObj, perm: 0o777, fd: d, target: name + del}
		}
		if !d.held() {
			return plink(name) // a memfd named by a path: no host object to reopen
		}
		if _, e := t.lstatGuest(name); e != lxENOENT {
			return plink(name)
		}
		// The name is gone but the descriptor still pins the object: reopen it.
		return &pnode{kind: pFdObj, perm: 0o777, fd: d, target: name + " (deleted)"}
	}
	return &pnode{kind: pFdObj, perm: 0o777, fd: d, target: t.fdTarget(d)}
}

// fdLinkStat answers a followed stat of /proc/<pid>/fd/<n> that names an object
// with no followable path (a pipe, socket, or an O_PATH fd whose name is gone):
// the kernel's magic link references the open object, so the result is that
// descriptor's own stat (identity equal to fstat(fd)), not the synthetic link
// node. A plain fd link to a live name is a symlink and resolves through its
// name before reaching here. ok is false for any non-fd-link path.
func (g *dguest) fdLinkStat(gp string) (lxStat, lxErrno, bool) {
	n, e, handled := g.pseudo(gp)
	if !handled || e != 0 || n.kind != pFdObj || n.fd == nil {
		return lxStat{}, 0, false
	}
	s, se := g.fdStatOf(n.fd)
	return s, se, true
}

func (fs *dfs) fdTarget(d *dfile) string {
	var f *os.File
	switch {
	case d.f != nil:
		f = d.f
	case d.stub >= 0 && d.stub < 3:
		f = fs.pst.stdio[d.stub]
	}
	if d.f != nil && strings.HasPrefix(d.gp, "anon_inode:") || d.pty != nil && strings.HasPrefix(d.gp, "/dev/") {
		return d.gp
	}
	if f == nil {
		return "/dev/null"
	}
	st, err := hostfs.FstatOf(f)
	if err != nil {
		return "/dev/null"
	}
	switch st.Mode() & lxSIFMT {
	case lxSIFIFO:
		return "pipe:[" + strconv.FormatUint(st.Ino()&0xffffffff, 10) + "]"
	case lxSIFSCK:
		return "socket:[" + strconv.FormatUint(st.Ino()&0xffffffff, 10) + "]"
	case lxSIFCHR:
		if hostIsTTY(f) {
			return "/dev/pts/0"
		}
		return "/dev/null"
	}
	if d.gp != "" && !strings.HasSuffix(d.gp, ":") {
		return d.gp
	}
	return "anon_inode:[unknown]"
}

func (fs *dfs) fdDir(t *dguest) *pnode {
	n := fs.fdList(t)
	n.look = func(name string) *pnode {
		fd, err := strconv.Atoi(name)
		if err != nil || fd < 0 || strconv.Itoa(fd) != name {
			return nil
		}
		if d, ok := t.ft.get(fd); ok {
			return t.fdNode(d)
		}
		return nil
	}
	return n
}

func (fs *dfs) fdList(t *dguest) *pnode {
	return pdir(func() []pchild {
		t.ft.mu.Lock()
		fds := make([]int, 0, len(t.ft.fds))
		for fd := range t.ft.fds {
			fds = append(fds, fd)
		}
		files := make(map[int]*dfile, len(fds))
		for _, fd := range fds {
			files[fd] = t.ft.fds[fd]
		}
		t.ft.mu.Unlock()
		sort.Ints(fds)
		out := make([]pchild, 0, len(fds))
		for _, fd := range fds {
			out = append(out, pchild{strconv.Itoa(fd), t.fdNode(files[fd])})
		}
		return out
	})
}

// ---- guest memory reads for /proc/self ---------------------------------------

// imgInfoOf returns the stub's record of the process's images. It is read
// through the process's own channel, so only the process itself can fetch it;
// others see what it fetched (or the parent's, inherited by fork).
func (g *dguest) imgInfoOf(t *dguest) *imgInfo {
	pi := t.pi
	pi.mu.Lock()
	img := pi.img
	pi.mu.Unlock()
	if img != nil || t.tgid != g.tgid {
		return img
	}
	addr := atomic.LoadUint64(&g.ch.page.pinfo)
	if addr == 0 {
		return nil
	}
	b, err := g.readMem(addr, 56)
	if err != nil {
		return nil
	}
	img = &imgInfo{le64(b), le64(b[8:]), le64(b[16:]), le64(b[24:]), le64(b[32:]), le64(b[40:]), le64(b[48:])}
	if img.sp == 0 {
		return nil
	}
	pi.mu.Lock()
	pi.img = img
	pi.mu.Unlock()
	return img
}

// auxvOf reads the auxiliary vector off the initial stack (self only).
func (g *dguest) auxvOf(t *dguest) []byte {
	img := g.imgInfoOf(t)
	if img == nil || t.tgid != g.tgid {
		return nil
	}
	rd := func(a uint64) (uint64, bool) {
		if a+8 > img.stackHi {
			return 0, false
		}
		b, err := g.readMem(a, 8)
		if err != nil {
			return 0, false
		}
		return le64(b), true
	}
	argc, ok := rd(img.sp)
	if !ok {
		return nil
	}
	a := img.sp + 8 + (argc+1)*8
	for { // skip envp
		v, ok := rd(a)
		if !ok {
			return nil
		}
		a += 8
		if v == 0 {
			break
		}
	}
	end := a
	for end+16 <= img.stackHi {
		v, ok := rd(end)
		if !ok {
			return nil
		}
		end += 16
		if v == 0 {
			break
		}
	}
	b, err := g.readMem(a, int(end-a))
	if err != nil {
		return nil
	}
	return b
}

func randomUUID() string {
	var b [16]byte
	f, err := os.Open("/dev/urandom")
	if err == nil {
		f.Read(b[:])
		f.Close()
	}
	b[6] = b[6]&0x0f | 0x40
	b[8] = b[8]&0x3f | 0x80
	const hx = "0123456789abcdef"
	var s []byte
	for i, c := range b {
		if i == 4 || i == 6 || i == 8 || i == 10 {
			s = append(s, '-')
		}
		s = append(s, hx[c>>4], hx[c&15])
	}
	return string(s)
}
